/**
 * Feeds every visitor can switch on without uploading anything. The metadata
 * and payloads are generated by scripts/build_via_feed.mts.
 */

import type { CityFeedMeta } from "./cityGtfs";
import builtinFeeds from "./builtinFeeds.json";

export interface BuiltinCityFeed extends CityFeedMeta {
  /** Static CityFeedPayload JSON, fetched the first time the feed is shown */
  url: string;
}

export const BUILTIN_FEEDS = builtinFeeds as BuiltinCityFeed[];
